Running command: cat > /tmp/check_detail.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <stddef.h>

typedef struct cs_wasm_op {
    int type;
    uint8_t size;
    union {
        int8_t int7;
        uint32_t varuint32;
        uint64_t varuint64;
        uint32_t uint32;
        uint64_t uint64;
        uint32_t immediate[2];
        struct { uint32_t length; uint32_t *target; uint32_t default_target; } brtable;
    };
} cs_wasm_op;

typedef struct cs_wasm {
    uint8_t op_count;
    cs_wasm_op *operands;
} cs_wasm;

typedef struct cs_detail {
    uint16_t regs_read[16];
    uint8_t regs_read_count;
    uint16_t regs_write[20];
    uint8_t regs_write_count;
    uint8_t groups[8];
    uint8_t groups_count;
    union {
        cs_wasm wasm;
    };
} cs_detail;

int main() {
    printf("sizeof(cs_detail) = %zu\n", sizeof(cs_detail));
    printf("offsetof(cs_detail, wasm) = %zu\n", offsetof(cs_detail, wasm));
    printf("sizeof(cs_wasm) = %zu\n", sizeof(cs_wasm));
    printf("memset size = %zu\n", offsetof(cs_detail, wasm) + sizeof(cs_wasm));
    printf("remaining = %zu\n", sizeof(cs_detail) - (offsetof(cs_detail, wasm) + sizeof(cs_wasm)));
    return 0;
}
EOF
gcc -o /tmp/check_detail /tmp/check_detail.c && /tmp/check_detail

message.content:
I see! At line 905, `insn_cache->detail = cs_mem_malloc(sizeof(cs_detail));` allocates a new `cs_detail` for each instruction. The memory from `malloc` is **uninitialized**. Then the WASM disassembler at line 696 does:
```c
memset(MI->flat_insn->detail, 0, offsetof(cs_detail, wasm)+sizeof(cs_wasm));
```

This zeros the first part of the struct. But what about the fields AFTER the union? Let me check:

```c
typedef struct cs_detail {
    uint16_t regs_read[16];      // 32 bytes
    uint8_t regs_read_count;     // 1 byte
    uint16_t regs_write[20];     // 40 bytes
    uint8_t regs_write_count;    // 1 byte
    uint8_t groups[8];           // 8 bytes
    uint8_t groups_count;        // 1 byte
    // padding
    union {
        ...
        cs_wasm wasm;
        ...
    };
} cs_detail;
```

The memset zeros from offset 0 to `offsetof(cs_detail, wasm) + sizeof(cs_wasm)`. The `wasm` field is the last field in the union, and the union is the last member of `cs_detail`. So the memset covers the entire struct.

Wait, but `sizeof(cs_wasm)` is 16 bytes (uint8_t + padding + pointer). And `offsetof(cs_detail, wasm)` gives the offset of the `wasm` field within the union. So the memset covers from the start of `cs_detail` to `offsetof(cs_detail, wasm) + 16`.

But the union might be larger than `cs_wasm` if other architecture structs are larger. Let me check:

